local BaitBoxMaker = {}
local PRODUCTS = {
    iron_baitbox = { name = "Železni škatla za vabe", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni škatla za vabe za ribištvo." },
    bronze_baitbox = { name = "Bronast škatla za vabe", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast škatla za vabe za ribištvo." },
    silver_baitbox = { name = "Srebrn škatla za vabe", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn škatla za vabe za ribištvo." },
    gilded_baitbox = { name = "Pozlačen škatla za vabe", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen škatla za vabe za ribištvo." },
    jewel_set_baitbox = { name = "Draguljast škatla za vabe", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast škatla za vabe za ribištvo." },
    royal_sovereign_baitbox = { name = "Kraljevski suveren škatla za vabe", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren škatla za vabe z biseri za krono." },
}
local BUILDINGS = {
    baitbox_workshop = { name = "Baitbox delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    baitbox_house = { name = "Baitbox hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_baitbox_atelier = { name = "Mojstrski baitbox atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_baitbox_palace = { name = "Suverena baitbox palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BaitBoxMaker.ironStock = 10; BaitBoxMaker.bronzeStock = 8; BaitBoxMaker.woodStock = 18; BaitBoxMaker.leatherStock = 12; BaitBoxMaker.silverStock = 8; BaitBoxMaker.goldStock = 6; BaitBoxMaker.jewelStock = 4; BaitBoxMaker.pearlStock = 4
BaitBoxMaker.productStock = {}; BaitBoxMaker.buildings = {}; BaitBoxMaker.maker = nil; BaitBoxMaker.activeMaking = {}; BaitBoxMaker.totalProducts = 0; BaitBoxMaker.dayTimer = 0
function BaitBoxMaker.init() BaitBoxMaker.ironStock=10; BaitBoxMaker.bronzeStock=8; BaitBoxMaker.woodStock=18; BaitBoxMaker.leatherStock=12; BaitBoxMaker.silverStock=8; BaitBoxMaker.goldStock=6; BaitBoxMaker.jewelStock=4; BaitBoxMaker.pearlStock=4; BaitBoxMaker.productStock={}; BaitBoxMaker.buildings={}; BaitBoxMaker.maker=nil; BaitBoxMaker.activeMaking={}; BaitBoxMaker.totalProducts=0; BaitBoxMaker.dayTimer=0; print("[BaitBoxMaker] Royal Bait Box Maker System initialized (6 products, 4 buildings)") end
function BaitBoxMaker.hireMaker(n,s) s=s or math.random(55,90); local c=565+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BaitBoxMaker.maker={name=n or ("Škatlar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Škatlar najet: %s (spretnost: %d)",BaitBoxMaker.maker.name,s),"success") end; return true end
function BaitBoxMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BaitBoxMaker.build(id) local ok,e=BaitBoxMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BaitBoxMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BaitBoxMaker.getQualityBonus() local b=0; for _,bd in ipairs(BaitBoxMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BaitBoxMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BaitBoxMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BaitBoxMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BaitBoxMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BaitBoxMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BaitBoxMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BaitBoxMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BaitBoxMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BaitBoxMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BaitBoxMaker.buildings==0 then return false,"Potrebna škatlena delavnica" end; if not BaitBoxMaker.maker then return false,"Potreben skatlar" end; return true end
function BaitBoxMaker.make(pt,qty) qty=qty or 1; local ok,e=BaitBoxMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BaitBoxMaker.ironStock=BaitBoxMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BaitBoxMaker.bronzeStock=BaitBoxMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BaitBoxMaker.woodStock=BaitBoxMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BaitBoxMaker.leatherStock=BaitBoxMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BaitBoxMaker.silverStock=BaitBoxMaker.silverStock-d.silverCost*qty end; if d.goldCost then BaitBoxMaker.goldStock=BaitBoxMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BaitBoxMaker.jewelStock=BaitBoxMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BaitBoxMaker.pearlStock=BaitBoxMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BaitBoxMaker.maker then t=math.max(1,t-math.floor(BaitBoxMaker.maker.skill/13)) end; table.insert(BaitBoxMaker.activeMaking,{id="${MAKER_LOWER}_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BaitBoxMaker.completeMaking(m) local q=1.0+(BaitBoxMaker.getQualityBonus()/100); if BaitBoxMaker.maker then q=q+(BaitBoxMaker.maker.skill/140) end; q=math.min(2.5,q); BaitBoxMaker.productStock[m.productType]=(BaitBoxMaker.productStock[m.productType] or 0)+m.quantity; BaitBoxMaker.totalProducts=BaitBoxMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BaitBoxMaker.maker then BaitBoxMaker.maker.itemsMade=BaitBoxMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BaitBoxMaker.maker.skill=math.min(100,BaitBoxMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Škatla izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"${MAKER_LOWER}.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function BaitBoxMaker.update(dt) if not _G.state then return end; BaitBoxMaker.dayTimer=BaitBoxMaker.dayTimer+dt; if BaitBoxMaker.dayTimer>=30 then BaitBoxMaker.dayTimer=0; for i=#BaitBoxMaker.activeMaking,1,-1 do local m=BaitBoxMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BaitBoxMaker.completeMaking(m); table.remove(BaitBoxMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BaitBoxMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BaitBoxMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BaitBoxMaker.getStats() return {ironStock=BaitBoxMaker.ironStock,bronzeStock=BaitBoxMaker.bronzeStock,woodStock=BaitBoxMaker.woodStock,leatherStock=BaitBoxMaker.leatherStock,silverStock=BaitBoxMaker.silverStock,goldStock=BaitBoxMaker.goldStock,jewelStock=BaitBoxMaker.jewelStock,pearlStock=BaitBoxMaker.pearlStock,productStock=BaitBoxMaker.productStock,numBuildings=#BaitBoxMaker.buildings,hasMaker=BaitBoxMaker.maker~=nil,makerName=BaitBoxMaker.maker and BaitBoxMaker.maker.name or "—",makerSkill=BaitBoxMaker.maker and BaitBoxMaker.maker.skill or 0,activeMaking=#BaitBoxMaker.activeMaking,totalProducts=BaitBoxMaker.totalProducts} end
return BaitBoxMaker
